#!/usr/bin/env python3
from __future__ import annotations

import sys
from pathlib import Path

LOCK_HEADERS = {
    "build.txt": (
        "# Generated by scripts/update_dependency_locks.sh; do not edit.",
        "# Source: pyproject.toml [build-system].requires",
        "# Install with: python -m pip install --require-hashes -r requirements/build.txt",
    ),
    "runtime.txt": (
        "# Generated by scripts/update_dependency_locks.sh; do not edit.",
        "# Source: pyproject.toml [project].dependencies",
        "# Install with: python -m pip install --require-hashes -r requirements/runtime.txt",
    ),
    "development.txt": (
        "# Generated by scripts/update_dependency_locks.sh; do not edit.",
        "# Source: pyproject.toml [project] plus the dev optional dependency group",
        "# Install with: python -m pip install --require-hashes -r requirements/development.txt",
    ),
}


def add_metadata(path: Path) -> None:
    try:
        header = LOCK_HEADERS[path.name]
    except KeyError as error:
        raise ValueError(f"No lock metadata is defined for {path.name}") from error
    body = path.read_text(encoding="utf-8").lstrip("\n")
    path.write_text("\n".join(header) + "\n\n" + body, encoding="utf-8")


def main() -> None:
    if len(sys.argv) < 2:
        raise SystemExit("usage: lock_file_metadata.py LOCK_FILE [LOCK_FILE ...]")
    for argument in sys.argv[1:]:
        add_metadata(Path(argument))


if __name__ == "__main__":
    main()
